-- Users and chats live in MySQL (5.6.5+ compatible). Messages / read receipts /
-- last-seen live in Firestore. IDs are UUIDs generated by the application;
-- timestamps are written by the application in UTC.
--
-- Invariants MySQL < 8.0.16 can't enforce with CHECK constraints (they are parsed
-- but ignored) are enforced in the service layer:
--   * direct chats have a direct_key and no name; group chats have a name and no direct_key.

CREATE TABLE IF NOT EXISTS users (
  id          CHAR(36)     NOT NULL,
  name        VARCHAR(100) NOT NULL,
  created_at  DATETIME(3)  NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS chats (
  id          CHAR(36)                NOT NULL,
  type        ENUM('direct', 'group') NOT NULL,
  name        VARCHAR(100)            NULL,
  -- For 1:1 chats: "<smallerUserId>:<largerUserId>". The UNIQUE key makes
  -- "create or get" race-safe: two concurrent requests can never create two chats
  -- for the same pair. NULL for group chats (NULLs don't collide in a UNIQUE key).
  direct_key  VARCHAR(80)             NULL,
  created_by  CHAR(36)                NULL,
  created_at  DATETIME(3)             NOT NULL,
  updated_at  DATETIME(3)             NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY chats_direct_key_uq (direct_key),
  KEY chats_created_by_idx (created_by),
  CONSTRAINT chats_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS chat_members (
  chat_id     CHAR(36)                 NOT NULL,
  user_id     CHAR(36)                 NOT NULL,
  role        ENUM('admin', 'member')  NOT NULL DEFAULT 'member',
  joined_at   DATETIME(3)              NOT NULL,
  PRIMARY KEY (chat_id, user_id),
  -- "List user chats" looks members up by user_id; the PK only covers (chat_id, user_id).
  KEY chat_members_user_id_idx (user_id),
  CONSTRAINT chat_members_chat_fk FOREIGN KEY (chat_id) REFERENCES chats (id) ON DELETE CASCADE,
  CONSTRAINT chat_members_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
